    role.objects.using(using).get_or_create(
        role_code="HR_MANAGER", defaults={"role_name": "인사 관리자"}
    )
    assignment.objects.using(using).filter(role_id="HR_LEAVE_APPROVER").update(role_id="HR_MANAGER")
    # 동일 사원에게 두 무기한 활성 배정이 있으면 하나만 남기고 나머지는 이력으로 보존한다.
    # 미래 시작·예정 회수 배정은 원래 기간을 임의로 바꾸지 않는다.
    now = timezone.now()
    seen = set()
    for row in assignment.objects.using(using).filter(
        role_id="HR_MANAGER", assigned_at__lte=now, revoked_at__isnull=True
    ).order_by("employee_id", "assigned_at", "employee_role_id"):
        if row.employee_id in seen:
            assignment.objects.using(using).filter(pk=row.pk).update(revoked_at=now)
        else:
            seen.add(row.employee_id)
    role.objects.using(using).filter(role_code="HR_LEAVE_APPROVER").delete()


